"""Simple banking module."""
from dataclasses import dataclass, field
from typing import List


@dataclass
class Account:
    account_id: str
    owner: str
    balance: float = 0.0

    def deposit(self, amount: float) -> None:
        """Deposit amount. Raises ValueError if amount <= 0."""
        raise NotImplementedError

    def withdraw(self, amount: float) -> None:
        """Withdraw amount. Raises ValueError if amount <= 0 or insufficient funds."""
        raise NotImplementedError


@dataclass
class Bank:
    name: str
    _accounts: dict = field(default_factory=dict)

    def create_account(self, account_id: str, owner: str, initial_balance: float = 0.0) -> Account:
        """Create and store a new account. Raises ValueError if account_id already exists."""
        raise NotImplementedError

    def get_account(self, account_id: str) -> Account:
        """Retrieve account by id. Raises KeyError if not found."""
        raise NotImplementedError

    def transfer(self, from_id: str, to_id: str, amount: float) -> None:
        """Transfer amount between accounts. Uses withdraw + deposit."""
        raise NotImplementedError

    def total_assets(self) -> float:
        """Sum of all account balances."""
        raise NotImplementedError
